To create a CSV downloader using web workers in Ember Octane, follow these steps:

1. Install the necessary dependencies:

```bash
ember install ember-cli-htmlbars
ember install ember-cli-json-api
ember install ember-cli-web-worker
```

2. Create a new service for handling the CSV download:

```bash
touch app/services/csv-downloader.js
```

3. Implement the CSV downloader service:

```javascript
import Service from '@ember/service';
import { get } from '@ember/object';
import { inject as service } from '@ember/service';
import { A } from '@ember/array';
import CSVBuilder from 'csv-builder';
import { worker } from 'ember-cli-web-worker';

export default Service.extend({
  store: service(),

  async downloadCSV(modelName, queryParams) {
    const { store } = this;
    const records = await store.query(modelName, queryParams);

    const csvBuilder = new CSVBuilder({
      delimiter: ',',
      newline: '\n',
    });

    const headers = records[0] && Object.keys(get(records[0], 'attributes'));
    const data = records.map((record) =>
      headers.map((header) => get(record, header))
    );

    const csv = csvBuilder.build({ headers, data });

    this._super.performAction('downloadCSV', { csv });
  },

  _performDownloadCSV(csv) {
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${get(this, 'modelName')}.csv`;
    a.click();
    window.URL.revokeObjectURL(url);
  },

  modelName: '',

  @worker
  async performAction(action, payload) {
